import{_ as i,a0 as l,w as s,s as p,I as n,x as e,a1 as t,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何配置一個 Docker Swarm 原生集羣 | LCTT x X-CMD","titleTemplate":false,"description":"如何配置一個 Docker Swarm 原生集羣 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何配置一個 Docker Swarm 原生集羣 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何配置一個 Docker Swarm 原生集羣 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150612 How to Configure Swarm Native Clustering for Docker","title":"如何配置一個 Docker Swarm 原生集羣","tag":"201507","desc":""},"relativePath":"201507/20150612 How to Configure Swarm Native Clustering for Docker.md","filePath":"[post].md"}'),m={name:"201507/20150612 How to Configure Swarm Native Clustering for Docker.md"};function c(w,r,g,k,u,h){const a=l("Link");return s(),p("div",null,[r[16]||(r[16]=n("h1",{id:"如何配置一個-docker-swarm-原生集羣",tabindex:"-1"},[e("如何配置一個 Docker Swarm 原生集羣 "),n("a",{class:"header-anchor",href:"#如何配置一個-docker-swarm-原生集羣","aria-label":"Permalink to “如何配置一個 Docker Swarm 原生集羣”"},"​")],-1)),n("p",null,[r[1]||(r[1]=e("嗨，大家好。今天我們來學一學Swarm相關的內容吧，我們將學習通過Swarm來創建Docker原生集羣。",-1)),t(a,{href:"https://docs.docker.com/swarm/"},{default:o(()=>[...r[0]||(r[0]=[e("Docker Swarm",-1)])]),_:1}),r[2]||(r[2]=e("是用於Docker的原生集羣項目，它可以將一個Docker主機池轉換成單個的虛擬主機。Swarm工作於標準的Docker API，所以任何可以和Docker守護進程通信的工具都可以使用Swarm來透明地伸縮到多個主機上。就像其它Docker項目一樣，Swarm遵循“內置電池，並可拆卸”的原則（LCTT 譯註：batteries included，內置電池原來是 Python 圈裏面對 Python 的一種讚譽，指自給自足，無需外求的豐富環境；but removable，並可拆卸應該指的是非強制耦合）。它附帶有一個開箱即用的簡單的後端調度程序，而且作為初始開發套件，也為其開發了一個可插拔不同後端的API。其目標在於為一些簡單的使用情況提供一個平滑的、開箱即用的體驗，並且它允許切換為更強大的後端，如Mesos，以用於大規模生產環境部署。Swarm配置和使用極其簡單。",-1))]),r[17]||(r[17]=d(`<p>這裏給大家提供Swarm 0.2開箱的即用一些特性。</p><ol><li>Swarm 0.2.0大約85%與Docker引擎兼容。</li><li>它支持資源管理。</li><li>它具有一些帶有限制和類同功能的高級調度特性。</li><li>它支持多個發現後端（hubs，consul，etcd，zookeeper）</li><li>它使用TLS加密方法進行安全通信和驗證。</li></ol><p>那麼，我們來看一看Swarm的一些相當簡單而簡用的使用步驟吧。</p><h3 id="_1-運行swarm的先決條件" tabindex="-1">1. 運行Swarm的先決條件 <a class="header-anchor" href="#_1-運行swarm的先決條件" aria-label="Permalink to “1. 運行Swarm的先決條件”">​</a></h3><p>我們必須在所有節點安裝Docker 1.4.0或更高版本。雖然各個節點的IP地址不需要要公共地址，但是Swarm管理器必須可以通過網絡訪問各個節點。</p><p><strong>注意</strong>：Swarm當前還處於beta版本，因此功能特性等還有可能發生改變，我們不推薦你在生產環境中使用。</p><h3 id="_2-創建swarm集羣" tabindex="-1">2. 創建Swarm集羣 <a class="header-anchor" href="#_2-創建swarm集羣" aria-label="Permalink to “2. 創建Swarm集羣”">​</a></h3><p>現在，我們將通過運行下面的命令來創建Swarm集羣。各個節點都將運行一個swarm節點代理，該代理會註冊、監控相關的Docker守護進程，並更新發現後端獲取的節點狀態。下面的命令會返回一個唯一的集羣ID標記，在啓動節點上的Swarm代理時會用到它。</p><p>在集羣管理器中：</p><pre><code># docker run swarm create
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/creating-swarm-cluster.png" alt="Creating Swarm Cluster"></p><h3 id="_3-啓動各個節點上的docker守護進程" tabindex="-1">3. 啓動各個節點上的Docker守護進程 <a class="header-anchor" href="#_3-啓動各個節點上的docker守護進程" aria-label="Permalink to “3. 啓動各個節點上的Docker守護進程”">​</a></h3><p>我們需要登錄進我們將用來創建集羣的每個節點，並在其上使用-H標記啓動Docker守護進程。它會保證Swarm管理器能夠通過TCP訪問到各個節點上的Docker遠程API。要啓動Docker守護進程，我們需要在各個節點內部運行以下命令。</p><pre><code># docker -H tcp://0.0.0.0:2375 -d
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/starting-docker-daemon.png" alt="Starting Docker Daemon"></p><h3 id="_4-添加節點" tabindex="-1">4. 添加節點 <a class="header-anchor" href="#_4-添加節點" aria-label="Permalink to “4. 添加節點”">​</a></h3><p>在啓用Docker守護進程後，我們需要添加Swarm節點到發現服務，我們必須確保節點IP可從Swarm管理器訪問到。要完成該操作，我們需要運行以下命令。</p><pre><code># docker run -d swarm join --addr=&lt;node_ip&gt;:2375 token://&lt;cluster_id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/adding-nodes-to-cluster.png" alt="Adding Nodes to Cluster"></p><p><strong>注意</strong>：我們需要用步驟2中獲取到的節點IP地址和集羣ID替換這裏的&lt;node_ip&gt;和&lt;cluster_id&gt;。</p><h3 id="_5-開啓swarm管理器" tabindex="-1">5. 開啓Swarm管理器 <a class="header-anchor" href="#_5-開啓swarm管理器" aria-label="Permalink to “5. 開啓Swarm管理器”">​</a></h3><p>現在，由於我們已經獲得了連接到集羣的節點，我們將啓動swarm管理器。我們需要在節點中運行以下命令。</p><pre><code># docker run -d -p &lt;swarm_port&gt;:2375 swarm manage token://&lt;cluster_id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/starting-swarm-manager.png" alt="Starting Swarm Manager"></p><h3 id="_6-檢查配置" tabindex="-1">6. 檢查配置 <a class="header-anchor" href="#_6-檢查配置" aria-label="Permalink to “6. 檢查配置”">​</a></h3><p>一旦管理運行起來後，我們可以通過運行以下命令來檢查配置。</p><pre><code># docker -H tcp://&lt;manager_ip:manager_port&gt; info
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/accessing-swarm-cluster.png" alt="Accessing Swarm Clusters"></p><p><strong>注意</strong>：我們需要替換&lt;manager_ip:manager_port&gt;為運行swarm管理器的主機的IP地址和端口。</p><h3 id="_7-使用docker-cli來訪問節點" tabindex="-1">7. 使用docker CLI來訪問節點 <a class="header-anchor" href="#_7-使用docker-cli來訪問節點" aria-label="Permalink to “7. 使用docker CLI來訪問節點”">​</a></h3><p>在一切都像上面説得那樣完美地完成後，這一部分是Docker Swarm最為重要的部分。我們可以使用Docker CLI來訪問節點，並在節點上運行容器。</p><pre><code># docker -H tcp://&lt;manager_ip:manager_port&gt; info
# docker -H tcp://&lt;manager_ip:manager_port&gt; run ...
</code></pre><h3 id="_8-監聽集羣中的節點" tabindex="-1">8. 監聽集羣中的節點 <a class="header-anchor" href="#_8-監聽集羣中的節點" aria-label="Permalink to “8. 監聽集羣中的節點”">​</a></h3><p>我們可以使用swarm list命令來獲取所有運行中節點的列表。</p><pre><code># docker run --rm swarm list token://&lt;cluster_id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/listing-swarm-nodes.png" alt="Listing Swarm Nodes"></p><h3 id="尾聲" tabindex="-1">尾聲 <a class="header-anchor" href="#尾聲" aria-label="Permalink to “尾聲”">​</a></h3><p>Swarm真的是一個有着相當不錯的功能的docker，它可以用於創建和管理集羣。它相當易於配置和使用，當我們在它上面使用限制器和類同器時它更為出色。高級調度程序是一個相當不錯的特性，它可以應用過濾器來通過端口、標籤、健康狀況來排除節點，並且它使用策略來挑選最佳節點。那麼，如果你有任何問題、評論、反饋，請在下面的評論框中寫出來吧，好讓我們知道哪些材料需要補充或改進。謝謝大家了！盡情享受吧 😃</p><hr>`,39)),n("p",null,[r[4]||(r[4]=e("via: ",-1)),t(a,{href:"http://linoxide.com/linux-how-to/configure-swarm-clustering-docker/"},{default:o(()=>[...r[3]||(r[3]=[e("http://linoxide.com/linux-how-to/configure-swarm-clustering-docker/",-1)])]),_:1})]),n("p",null,[r[8]||(r[8]=e("作者：",-1)),t(a,{href:"http://linoxide.com/author/arunp/"},{default:o(()=>[...r[5]||(r[5]=[e("Arun Pyasi",-1)])]),_:1}),r[9]||(r[9]=e(" 譯者：",-1)),t(a,{href:"https://github.com/GOLinux"},{default:o(()=>[...r[6]||(r[6]=[e("GOLinux",-1)])]),_:1}),r[10]||(r[10]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...r[7]||(r[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[r[13]||(r[13]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...r[11]||(r[11]=[e("LCTT",-1)])]),_:1}),r[14]||(r[14]=e(" 原創翻譯，",-1)),t(a,{href:"https://linux.cn/"},{default:o(()=>[...r[12]||(r[12]=[e("Linux中國",-1)])]),_:1}),r[15]||(r[15]=e(" 榮譽推出",-1))])])}const x=i(m,[["render",c]]);export{D as __pageData,x as default};
